CREATE TABLE phase_definitions (
    code TEXT NOT NULL CHECK(code IN ('PRE','P1','P2')),
    version INTEGER NOT NULL CHECK(version > 0),
    payload_json TEXT NOT NULL CHECK(json_valid(payload_json)),
    definition_hash TEXT NOT NULL CHECK(length(definition_hash)=64),
    PRIMARY KEY(code, version)
);
INSERT INTO phase_definitions(code,version,payload_json,definition_hash) VALUES
('PRE',1,'{"code":"PRE","version":1,"name":"PRE — Contexto previo","objective":"Explicitar el propósito, la incertidumbre y el punto de partida antes de orientar la lectura.","keyQuestions":["¿Para qué voy a leer este paper?","¿Qué incertidumbre quiero reducir?","¿Qué sé ya?","¿Qué espero obtener y con qué profundidad?","¿Qué tipo de revisión he comprobado?"],"doItems":["Explicitar decisiones propias y desconocimientos.","Confirmar el tipo bibliográfico y la disponibilidad del PDF."],"dontItems":["Inferir resultados a partir del título.","Tratar un tipo desconocido por defecto como revisado."],"considerations":["Desconocido y no aplicable requieren explicación cuando estén permitidos.","La comprobación revisa si has procesado las salidas; no puntúa su calidad científica."],"requiredOutputs":[{"key":"purpose","label":"Propósito de lectura","prompt":"Explica para qué lees este paper.","required":true,"allowedResolutions":["PENDING","ANSWERED"],"ruleKey":"answerProcessed"},{"key":"uncertainty_target","label":"Incertidumbre que quieres reducir","prompt":"Formula qué incertidumbre quieres reducir.","required":true,"allowedResolutions":["PENDING","ANSWERED"],"ruleKey":"answerProcessed"},{"key":"baseline","label":"Conocimiento previo","prompt":"Describe tu punto de partida; si no puedes establecerlo, explica el desconocimiento o la no aplicabilidad.","required":true,"allowedResolutions":["PENDING","ANSWERED","UNKNOWN","NOT_APPLICABLE"],"ruleKey":"answerProcessed"},{"key":"expected_outcome","label":"Resultado esperado de la lectura","prompt":"Explica qué esperas saber; si la lectura es exploratoria y todavía no puedes concretarlo, explica por qué.","required":true,"allowedResolutions":["PENDING","ANSWERED","UNKNOWN"],"ruleKey":"answerProcessed"},{"key":"desired_depth","label":"Profundidad prevista","prompt":"Describe la profundidad de lectura que has decidido.","required":true,"allowedResolutions":["PENDING","ANSWERED"],"ruleKey":"answerProcessed"},{"key":"review_type","label":"Tipo bibliográfico confirmado","prompt":"Confirma explícitamente el tipo bibliográfico registrado del paper, sin editarlo aquí. Si figura como desconocido, explica por qué no has podido determinarlo.","required":true,"allowedResolutions":["PENDING","ANSWERED","UNKNOWN"],"ruleKey":"answerProcessed"}],"completionRules":["answerProcessed","paperHasActiveDocument"],"definitionHash":"ee2f0e54c352475dc5896080b3a7ed8f5425b637a3712e4a77f721a942cc4a7f"}','ee2f0e54c352475dc5896080b3a7ed8f5425b637a3712e4a77f721a942cc4a7f'),
('P1',1,'{"code":"P1","version":1,"name":"P1 — Orientación","objective":"Delimitar alcance, mensaje y utilidad para decidir el recorrido de lectura.","keyQuestions":["¿Qué cubre y qué deja fuera?","¿Qué tipo de revisión y horizonte de literatura presenta?","¿Cuál es su mensaje principal?","¿Qué relevancia tiene para mi propósito y qué lectura decido?"],"doItems":["Distinguir lo declarado por la fuente de tu valoración.","Registrar por separado relevancia y decisión de lectura."],"dontItems":["Inventar fechas o metodología ausentes.","Escribir una decisión en texto libre en lugar de elegir la opción correspondiente."],"considerations":["Continuar, lectura ligera y archivar completan P1 cuando has procesado las salidas requeridas.","Guardar la decisión no la ejecuta.","La organización del campo es una salida opcional."],"requiredOutputs":[{"key":"scope","label":"Alcance","prompt":"Resume qué aborda el paper; explica si no puede determinarse.","required":true,"allowedResolutions":["PENDING","ANSWERED","UNKNOWN"],"ruleKey":"answerProcessed"},{"key":"out_of_scope","label":"Fuera de alcance","prompt":"Describe qué deja fuera; explica si no lo declara o si no es aplicable.","required":true,"allowedResolutions":["PENDING","ANSWERED","UNKNOWN","NOT_APPLICABLE"],"ruleKey":"answerProcessed"},{"key":"review_type","label":"Enfoque de revisión según la fuente","prompt":"Describe cómo se presenta la revisión y qué metodología declara la fuente. Esta respuesta caracteriza el texto y no edita el tipo bibliográfico del paper; explica lo desconocido.","required":true,"allowedResolutions":["PENDING","ANSWERED","UNKNOWN"],"ruleKey":"answerProcessed"},{"key":"literature_cutoff","label":"Horizonte de literatura","prompt":"Registra el horizonte o fecha de corte; explica el desconocimiento o por qué no es aplicable.","required":true,"allowedResolutions":["PENDING","ANSWERED","UNKNOWN","NOT_APPLICABLE"],"ruleKey":"answerProcessed"},{"key":"core_message","label":"Mensaje principal","prompt":"Resume el mensaje principal; explica si todavía no puede determinarse.","required":true,"allowedResolutions":["PENDING","ANSWERED","UNKNOWN"],"ruleKey":"answerProcessed"},{"key":"relevance_decision","label":"Relevancia y decisión de lectura","prompt":"Elige una valoración de relevancia y una decisión: continuar, lectura ligera o archivar.","required":true,"allowedResolutions":["PENDING","ANSWERED"],"ruleKey":"p1DecisionProcessed"},{"key":"field_organization","label":"Organización del campo","prompt":"Si te resulta útil, registra cómo organiza el campo; explica las ausencias que decidas registrar.","required":false,"allowedResolutions":["PENDING","ANSWERED","UNKNOWN","NOT_APPLICABLE"],"ruleKey":"answerProcessed"}],"completionRules":["answerProcessed","p1DecisionProcessed"],"definitionHash":"8e2c71f5d3f8578ff940c9903086f982aedca69adbb704c8fa3afe6381359150"}','8e2c71f5d3f8578ff940c9903086f982aedca69adbb704c8fa3afe6381359150'),
('P2',1,'{"code":"P2","version":1,"name":"P2 — Modelo conceptual","objective":"Procesar preguntas, síntesis, conceptos, relaciones y referencias, conservando trazabilidad y una decisión explícita sobre candidatos P3.","keyQuestions":["¿Cómo responde el paper a las preguntas de lectura?","¿Qué síntesis y conceptos pertinentes obtengo?","¿Qué relaciones o contradicciones encuentro?","¿Qué referencias clasifico y qué candidatos justifico para P3?"],"doItems":["Conservar notas y enlaces consultables de lo que captures.","Distinguir fuente, interpretación e hipótesis.","Justificar la ausencia de contradicciones y de candidatos."],"dontItems":["Inventar conceptos, relaciones o contradicciones para superar la comprobación.","Presentar P2 completada como validación de las afirmaciones o cierre de P3/P4."],"considerations":["No se exige una cantidad mínima de conceptos, relaciones o contradicciones.","Los candidatos son afirmaciones o preguntas enlazadas al paper.","Cero candidatos requiere justificación; con candidatos no se requiere una justificación de ausencia."],"requiredOutputs":[{"key":"main_questions_processed","label":"Preguntas principales procesadas","prompt":"Explica cómo has procesado las preguntas principales; justifica el desconocimiento o la no aplicabilidad.","required":true,"allowedResolutions":["PENDING","ANSWERED","UNKNOWN","NOT_APPLICABLE"],"ruleKey":"p2ArtifactPresent"},{"key":"field_synthesis","label":"Síntesis del campo","prompt":"Enlaza tus notas de síntesis y resúmela; si no puedes formularla o no hay material pertinente, explica la ausencia.","required":true,"allowedResolutions":["PENDING","ANSWERED","UNKNOWN"],"ruleKey":"p2ArtifactPresent"},{"key":"relevant_concepts_reviewed","label":"Conceptos pertinentes revisados","prompt":"Resume qué conceptos has revisado y conserva los capturados como notas consultables; justifica el desconocimiento o la no aplicabilidad.","required":true,"allowedResolutions":["PENDING","ANSWERED","UNKNOWN","NOT_APPLICABLE"],"ruleKey":"p2ArtifactPresent"},{"key":"meaningful_relations_reviewed","label":"Relaciones pertinentes revisadas","prompt":"Resume qué relaciones has revisado y conserva las capturadas como enlaces; justifica el desconocimiento o la no aplicabilidad.","required":true,"allowedResolutions":["PENDING","ANSWERED","UNKNOWN","NOT_APPLICABLE"],"ruleKey":"p2ArtifactPresent"},{"key":"contradictions_reviewed","label":"Contradicciones revisadas","prompt":"Describe las contradicciones revisadas o explica su ausencia; no inventes ninguna.","required":true,"allowedResolutions":["PENDING","ANSWERED","UNKNOWN","NOT_APPLICABLE"],"ruleKey":"p2ArtifactPresent"},{"key":"references_classified","label":"Referencias clasificadas","prompt":"Resume la clasificación de las referencias y conserva las capturadas; justifica el desconocimiento o la no aplicabilidad.","required":true,"allowedResolutions":["PENDING","ANSWERED","UNKNOWN","NOT_APPLICABLE"],"ruleKey":"p2ArtifactPresent"},{"key":"p3_candidates_or_justification","label":"Candidatos P3 o justificación de ausencia","prompt":"Selecciona candidatos pertinentes con motivo o explica por qué no has seleccionado ninguno.","required":true,"allowedResolutions":["PENDING","ANSWERED"],"ruleKey":"p2ArtifactPresent"}],"completionRules":["answerProcessed","p2ArtifactPresent","p2NoCandidatesJustified"],"definitionHash":"2c8059fce6d4beadf442ea9d9f5d063906b5e1542f6fe0972e1c6f85be509393"}','2c8059fce6d4beadf442ea9d9f5d063906b5e1542f6fe0972e1c6f85be509393');
CREATE TABLE paper_phases (
    paper_id TEXT NOT NULL REFERENCES papers(id),
    phase_code TEXT NOT NULL CHECK(phase_code IN ('PRE','P1','P2')),
    definition_version INTEGER NOT NULL,
    state TEXT NOT NULL CHECK(state IN ('NOT_STARTED','IN_PROGRESS','COMPLETED','NEEDS_REVIEW')),
    revision INTEGER NOT NULL CHECK(revision >= 0),
    completed_at TEXT,
    accepted_gate_snapshot_json TEXT CHECK(accepted_gate_snapshot_json IS NULL OR json_valid(accepted_gate_snapshot_json)),
    accepted_gate_snapshot_hash TEXT CHECK(accepted_gate_snapshot_hash IS NULL OR length(accepted_gate_snapshot_hash)=64),
    PRIMARY KEY(paper_id,phase_code),
    FOREIGN KEY(phase_code,definition_version) REFERENCES phase_definitions(code,version),
    CHECK((accepted_gate_snapshot_json IS NULL) = (accepted_gate_snapshot_hash IS NULL))
);
CREATE TABLE phase_answers (
    paper_id TEXT NOT NULL,
    phase_code TEXT NOT NULL,
    question_key TEXT NOT NULL CHECK(length(question_key)>0),
    answer_text TEXT NOT NULL CHECK(length(answer_text)<=20000),
    structured_value_json TEXT CHECK(structured_value_json IS NULL OR json_valid(structured_value_json)),
    resolution TEXT NOT NULL CHECK(resolution IN ('PENDING','ANSWERED','UNKNOWN','NOT_APPLICABLE')),
    explanation TEXT CHECK(explanation IS NULL OR length(explanation)<=5000),
    revision INTEGER NOT NULL CHECK(revision > 0),
    updated_at TEXT NOT NULL,
    PRIMARY KEY(paper_id,phase_code,question_key),
    FOREIGN KEY(paper_id,phase_code) REFERENCES paper_phases(paper_id,phase_code)
);
CREATE INDEX phase_answers_paper_phase ON phase_answers(paper_id,phase_code);
UPDATE papers
SET processing_initialized = CASE WHEN processing_initialized=0 AND current_phase IS NULL THEN 1 ELSE 2 END,
    current_phase = CASE WHEN processing_initialized=0 AND current_phase IS NULL THEN 'PRE' ELSE current_phase END;
INSERT INTO paper_phases(paper_id,phase_code,definition_version,state,revision)
SELECT id,'PRE',1,'IN_PROGRESS',1 FROM papers WHERE processing_initialized=1;
INSERT INTO paper_phases(paper_id,phase_code,definition_version,state,revision)
SELECT id,'P1',1,'NOT_STARTED',0 FROM papers WHERE processing_initialized=1;
INSERT INTO paper_phases(paper_id,phase_code,definition_version,state,revision)
SELECT id,'P2',1,'NOT_STARTED',0 FROM papers WHERE processing_initialized=1;
